#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <stdint.h>
#include <mypaint-brush.h>
#include <mypaint-fixed-tiled-surface.h>
#include <mypaint-tiled-surface.h>
int main(int argc,char**argv){if(argc!=2)return 2;for(int variant=0;variant<3;variant++){MyPaintFixedTiledSurface *surface=mypaint_fixed_tiled_surface_new(512,512);MyPaintSurface *base=mypaint_fixed_tiled_surface_interface(surface);MyPaintBrush *brush=mypaint_brush_new();mypaint_brush_from_defaults(brush);mypaint_brush_set_base_value(brush,MYPAINT_BRUSH_SETTING_RADIUS_LOGARITHMIC,log(10));mypaint_brush_set_base_value(brush,MYPAINT_BRUSH_SETTING_HARDNESS,variant==0?.95:variant==1?.65:.35);mypaint_brush_set_base_value(brush,MYPAINT_BRUSH_SETTING_OPAQUE,1);mypaint_brush_set_base_value(brush,MYPAINT_BRUSH_SETTING_DABS_PER_ACTUAL_RADIUS,3);mypaint_brush_set_base_value(brush,MYPAINT_BRUSH_SETTING_COLOR_H,.47);mypaint_brush_set_base_value(brush,MYPAINT_BRUSH_SETTING_COLOR_S,.7);mypaint_brush_set_base_value(brush,MYPAINT_BRUSH_SETTING_COLOR_V,.85);mypaint_brush_set_mapping_n(brush,MYPAINT_BRUSH_SETTING_RADIUS_LOGARITHMIC,MYPAINT_BRUSH_INPUT_PRESSURE,2);mypaint_brush_set_mapping_point(brush,MYPAINT_BRUSH_SETTING_RADIUS_LOGARITHMIC,MYPAINT_BRUSH_INPUT_PRESSURE,0,0,-1);mypaint_brush_set_mapping_point(brush,MYPAINT_BRUSH_SETTING_RADIUS_LOGARITHMIC,MYPAINT_BRUSH_INPUT_PRESSURE,1,1,.7);
for(int row=0;row<4;row++){mypaint_brush_reset(brush);mypaint_brush_new_stroke(brush);mypaint_surface_begin_atomic(base);for(int i=0;i<=400;i++){double t=i/400.;double x=50+412*t,y=85+row*110+25*sin(t*4*M_PI);mypaint_brush_stroke_to(brush,base,x,y,.2+.75*sin(t*M_PI),0,0,.01);}MyPaintRectangle roi;mypaint_surface_end_atomic(base,&roi);}
unsigned char*rgb=malloc(512*512*3);long coverage=0;for(int ty=0;ty<8;ty++)for(int tx=0;tx<8;tx++){MyPaintTileRequest request;mypaint_tile_request_init(&request,0,tx,ty,1);mypaint_tiled_surface_tile_request_start((MyPaintTiledSurface*)surface,&request);if(!request.buffer)return 3;for(int y=0;y<64;y++)for(int x=0;x<64;x++){int i=(y*64+x)*4,o=((ty*64+y)*512+tx*64+x)*3;double a=request.buffer[i+3]/32768.;if(request.buffer[i]<30000||request.buffer[i+1]<30000||request.buffer[i+2]<30000)coverage++;for(int c=0;c<3;c++){double value=request.buffer[i+c]/32768.+(1-a)*.04;rgb[o+c]=(unsigned char)(255*fmin(1,fmax(0,value)));}}mypaint_tiled_surface_tile_request_end((MyPaintTiledSurface*)surface,&request);}if(coverage<5000||coverage>150000)return 4;char name[4096];snprintf(name,sizeof(name),"%s/render-%d.ppm",argv[1],variant);FILE*f=fopen(name,"wb");fprintf(f,"P6\n512 512\n255\n");fwrite(rgb,1,512*512*3,f);fclose(f);printf("%d coverage %ld\n",variant,coverage);free(rgb);mypaint_brush_unref(brush);mypaint_surface_unref(base);}return 0;}
